(()=>{'use strict';const c=window.OVERDRIVE_CONFIG||{};document.querySelectorAll('.brand>span:last-child').forEach(el=>{el.firstChild.textContent=c.name||'OVERDRIVE';const small=el.querySelector('small');if(small)small.textContent=c.subtitle||'RACING COMMUNITY';});if(/^#[0-9a-f]{6}$/i.test(c.accent||''))document.documentElement.style.setProperty('--red',c.accent);const h=document.querySelector('.hero h1');if(h){h.replaceChildren(document.createTextNode(c.headlineFirst||'BUILT FOR'),document.createElement('br'));const em=document.createElement('em');em.textContent=c.headlineSecond||'THE NEXT LEVEL.';h.append(em);}if(c.tagline){const p=document.querySelector('.hero-inner>p');if(p)p.textContent=c.tagline;}if(c.eventDate&&!Number.isNaN(Date.parse(c.eventDate)))document.querySelectorAll('[data-countdown]').forEach(e=>e.dataset.countdown=c.eventDate);const form=document.querySelector('#contact-form');if(form&&/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(c.contactEmail||'')){const b=document.createElement('button');b.type='button';b.className='button secondary';b.textContent='Entwurf im E-Mail-Programm öffnen';b.onclick=()=>{const text=document.querySelector('#draft-text').value;if(text)location.href='mailto:'+encodeURIComponent(c.contactEmail)+'?subject='+encodeURIComponent('Website-Anfrage')+'&body='+encodeURIComponent(text);};document.querySelector('#draft-result .button-row').append(b);}})();